function f = HS33_f(x)
f = x(3) + (x(1) - 3).*(x(1) - 2).*(x(1) - 1);
end

function g = HS33_g(x)
g = zeros(3, 1);
g(1) = (x(1) - 3).*(x(1) - 2) + (x(1) - 3).*(x(1) - 1) + (x(1) - 2).*(x(1) - 1);
g(3) = 1;
end

function c = HS33_c(x)
c = zeros(2, 1);
c(1) = -x(1).^2 - x(2).^2 + x(3).^2;
c(2) = x(1).^2 + x(2).^2 + x(3).^2 - 4;
end

function J = HS33_J(x)
J = zeros(2, 3);
J(1, 1) = -2*x(1);
J(1, 2) = -2*x(2);
J(1, 3) = 2*x(3);
J(2, 1) = 2*x(1);
J(2, 2) = 2*x(2);
J(2, 3) = 2*x(3);
end
